        const courierSub = supabase.channel('public:couriers').on('postgres_changes', { event: '*', schema: 'public', table: 'couriers' }, () => fetchData()).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
            supabase.removeChannel(courierSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

