export const Register: React.FC = () => {
    const { signup, registerCourier } = useApp();
    const navigate = useNavigate();
    const location = useLocation();

    // Check if a role was passed in state (e.g., from "Start Selling" button)
    const preSelectedRole = location.state?.role as Role | undefined;

    const [fullName, setFullName] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [phoneNumber, setPhoneNumber] = useState('');
    // Default to 'buyer', or the pre-selected role if available
    const [role, setRole] = useState<Role>(preSelectedRole || 'buyer');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSignup = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        const result = await signup(email, password, fullName, role, phoneNumber);

        if (result.success) {
            // Special handling for Courier: Register them in courier table immediately
            if (role === 'courier') {
                // Pass the user ID explicitly to avoid state race conditions
                const userId = result.user?.id;
                const courierRes = await registerCourier({ fullName, phoneNumber }, userId);

                setIsLoading(false);
                if (courierRes.success) {
                    alert("Courier account created! Please wait for admin verification.");
                    // REDIRECT TO BUYER DASHBOARD OR PROFILE - NOT DELIVERY DASHBOARD
                    // Because they are pending and don't have the role yet
                    navigate('/buyer/profile');
                } else {
                    setError("Account created but failed to submit courier application. Please contact support.");
                }
            } else if (role === 'vendor') {
                 setIsLoading(false);
                 navigate('/vendor/onboarding');
            } else {
                 setIsLoading(false);
                 navigate('/buyer/dashboard');
            }
        } else {
            setIsLoading(false);
            setError(result.error || 'Registration failed. Email might be taken.');
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-white relative overflow-hidden">
             <div className="absolute top-[-10%] left-[-10%] w-64 h-64 bg-primary/10 rounded-full blur-3xl"></div>

             <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-slide-up">
                <div className="mb-6 text-center">
                    <h1 className="text-3xl font-display font-extrabold text-gray-900">Create Account</h1>
                    <p className="text-gray-500 mt-2">Join the campus marketplace</p>
                </div>

                {error && (
                    <div className="bg-red-50 border border-red-100 text-red-600 text-sm p-3 rounded-xl mb-4">
                        {error}
                    </div>
                )}

                <form onSubmit={handleSignup} className="space-y-5">
                    <Input 
                        label="Full Name" 
                        icon="user" 
                        placeholder="John Doe" 
                        value={fullName} 
                        onChange={e => setFullName(e.target.value)} 
                        required
                    />

                    <Input 
                        label="Email Address" 
                        icon="envelope" 
                        type="email" 
                        placeholder="you@university.edu" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        required
                    />

                    <Input 
                        label="Phone Number" 
                        icon="phone" 
                        type="tel" 
                        placeholder="050 123 4567" 
                        value={phoneNumber} 
                        onChange={e => setPhoneNumber(e.target.value)} 
                        required
                    />

                    <Input 
                        label="Password" 
                        icon="lock" 
                        type="password"
                        placeholder="Create a password" 
                        value={password}
                        onChange={e => setPassword(e.target.value)}
                        required
                        minLength={6}
                    />

                    {/* Only show role selection if NOT pre-selected */}
                    {!preSelectedRole ? (
                        <div>
                            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 ml-1">I want to...</label>
                            <div className="grid grid-cols-3 gap-2">
                                <div 
                                    onClick={() => setRole('buyer')}
                                    className={`cursor-pointer rounded-2xl p-2 border-2 text-center transition-all flex flex-col items-center justify-center gap-1 h-20 ${role === 'buyer' ? 'border-primary bg-primary/5 text-primary font-bold' : 'border-gray-100 text-gray-500'}`}
                                >
                                    <i className="fa-solid fa-bag-shopping text-lg"></i>
                                    <span className="text-[10px]">Buy</span>
                                </div>
                                <div 
                                    onClick={() => setRole('vendor')}
                                    className={`cursor-pointer rounded-2xl p-2 border-2 text-center transition-all flex flex-col items-center justify-center gap-1 h-20 ${role === 'vendor' ? 'border-secondary bg-secondary/5 text-secondary font-bold' : 'border-gray-100 text-gray-500'}`}
                                >
                                    <i className="fa-solid fa-store text-lg"></i>
                                    <span className="text-[10px]">Sell</span>
                                </div>
                                <div 
                                    onClick={() => setRole('courier')}
                                    className={`cursor-pointer rounded-2xl p-2 border-2 text-center transition-all flex flex-col items-center justify-center gap-1 h-20 ${role === 'courier' ? 'border-blue-500 bg-blue-50 text-blue-600 font-bold' : 'border-gray-100 text-gray-500'}`}
                                >
                                    <i className="fa-solid fa-motorcycle text-lg"></i>
                                    <span className="text-[10px]">Deliver</span>
                                </div>
                            </div>
                        </div>
                    ) : (
                        // Show badge indicating pre-selected role
                        <div className="bg-secondary/10 border border-secondary/20 p-3 rounded-xl flex items-center justify-center text-secondary text-sm font-bold">
                            <i className="fa-solid fa-store mr-2"></i> Registering as a Vendor
                        </div>
                    )}

                    <Button 
                        fullWidth 
                        size="lg" 
                        type="submit"
                        disabled={isLoading}
                        className="shadow-xl shadow-primary/30 mt-2"
                    >
                        {isLoading ? 'Creating Account...' : 'Sign Up'}
                    </Button>
                </form>

                <div className="mt-8 text-center text-sm text-gray-500">
                    Already have an account? <Link to="/login" className="font-bold text-primary hover:text-primaryDark transition-colors">Log In</Link>
                </div>
             </div>
        </div>
    );
}

