export const VendorDashboard: React.FC = () => {
  const { products, orders, currentUser, vendors, isDataLoading, logout } = useApp();
  const navigate = useNavigate();

  const currentVendor = useMemo(() => vendors.find(v => v.userId === currentUser?.id), [vendors, currentUser]);
  const vendorId = currentVendor?.vendorId;

  // Check: If vendor profile exists but is NOT approved, block access
  if (!isDataLoading && currentVendor && !currentVendor.isApproved) {
       return (
           <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 p-6 text-center">
               <div className="bg-white p-8 rounded-2xl shadow-lg max-w-sm">
                   <div className="w-16 h-16 bg-yellow-100 rounded-full flex items-center justify-center mx-auto mb-4 text-yellow-600 text-2xl">
                     <i className="fa-solid fa-clock"></i>
                   </div>
                   <h2 className="text-xl font-bold mb-2">Under Review</h2>
                   <p className="text-gray-500 mb-6 text-sm">Your store is pending admin approval. You cannot access the dashboard yet.</p>
                   <Button fullWidth onClick={() => { logout(); navigate('/login'); }}>Sign Out</Button>
               </div>
           </div>
       );
  }

  // New Check: If user is vendor role but has no profile, prompt to onboard
  if (!isDataLoading && !currentVendor && currentUser) {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-50 p-6 flex-col text-center">
              <div className="bg-white p-8 rounded-2xl shadow-lg max-w-sm">
                  <div className="w-16 h-16 bg-yellow-100 rounded-full flex items-center justify-center mx-auto mb-4 text-yellow-600 text-2xl">
                    <i className="fa-solid fa-store"></i>
                  </div>
                  <h2 className="text-xl font-bold mb-2">Store Setup Incomplete</h2>
                  <p className="text-gray-500 mb-6 text-sm">You have a vendor account but haven't set up your store details yet.</p>
                  <Button fullWidth onClick={() => navigate('/vendor/onboarding')}>Complete Store Setup</Button>
              </div>
          </div>
      )
  }

  // Optimized Calculations
  const pendingOrders = useMemo(() => {
      return orders.filter(o => o.vendorId === vendorId && o.status !== 'delivered');
  }, [orders, vendorId]);

  const totalSales = useMemo(() => {
      return orders.filter(o => o.vendorId === vendorId).reduce((acc, curr) => {
          // Subtract delivery fee as it belongs to courier
          const saleValue = curr.total - (curr.deliveryFee || 0);
          return acc + saleValue;
      }, 0);
  }, [orders, vendorId]);

  return (
    <div className="p-4 min-h-screen bg-gray-50 pb-24 animate-fade-in pb-safe">
        <div className="flex justify-between items-center mb-6">
            <h1 className="text-2xl font-bold text-gray-900">Dashboard</h1>
            <Button size="sm" onClick={() => navigate('/vendor/products/new')}>+ Add Product</Button>
        </div>

        <div className="grid grid-cols-2 gap-4 mb-6">
            <Card className="p-4 border-l-4 border-primary">
                <h3 className="text-gray-500 text-xs uppercase font-bold">Total Sales</h3>
                <p className="text-2xl font-bold mt-1 text-gray-900">₵{totalSales.toFixed(2)}</p>
            </Card>
            <Card className="p-4 border-l-4 border-accent">
                <h3 className="text-gray-500 text-xs uppercase font-bold">Active Orders</h3>
                <p className="text-2xl font-bold mt-1 text-gray-900">{pendingOrders.length}</p>
            </Card>
        </div>

        <h3 className="font-bold text-lg mb-3 text-gray-800">Recent Orders</h3>
        <div className="space-y-3 mb-8">
            {pendingOrders.length === 0 ? <p className="text-gray-500 text-sm bg-white p-4 rounded-xl shadow-sm">No active orders.</p> : 
             pendingOrders.slice(0, 3).map(order => (
                 <Card key={order.id} className="p-4" onClick={() => navigate('/vendor/orders')}>
                     <div className="flex justify-between mb-2">
                         <span className="font-bold text-sm">Order #{order.id.slice(-4)}</span>
                         <Badge color="blue">{order.status.replace('_', ' ')}</Badge>
                     </div>
                     <p className="text-xs text-gray-500 mb-2">{order.items.length} items • {order.deliveryOption}</p>
                 </Card>
             ))}
        </div>
    </div>
  );
};

