            <div className="bg-white p-4 shadow-sm sticky top-0 z-10 flex items-center gap-3">
                <button onClick={() => navigate(-1)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100"><i className="fa-solid fa-arrow-left"></i></button>
                <h1 className="text-xl font-bold font-display">Wishlist ({favorites.length})</h1>
            </div>

            <div className="p-4 grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                {wishlistItems.length === 0 ? (
                    <div className="col-span-full text-center py-20 text-gray-400">
                        <i className="fa-regular fa-heart text-4xl mb-4 opacity-10"></i>
                        <p className="text-sm font-bold">Your wishlist is empty.</p>
                        <Button className="mt-4" onClick={() => navigate('/buyer/dashboard')}>Explore Products</Button>
                    </div>
                ) : (
                    wishlistItems.map(p => (
                        <div key={p.id} className="bg-white rounded-2xl overflow-hidden shadow-card border border-gray-100 group relative flex flex-col h-full animate-fade-in">
                            <div className="aspect-square w-full relative overflow-hidden bg-gray-50">
                                <img src={p.images[0]} className="w-full h-full object-cover" onClick={() => navigate(`/buyer/product/${p.id}`)} />
                                <button onClick={(e) => { e.stopPropagation(); toggleFavorite(p.id); }} className="absolute top-2 right-2 z-10 w-7 h-7 rounded-full bg-white/90 text-red-500 flex items-center justify-center shadow-sm active:scale-90"><i className="fa-solid fa-trash text-xs"></i></button>
                            </div>
                            <div className="p-3 flex flex-col flex-grow justify-between">
                                <h3 className="text-xs font-bold text-gray-800 line-clamp-2 mb-1">{p.title}</h3>
                                <div className="flex items-center justify-between mt-1">
                                    <span className="text-sm font-black text-gray-900">₵{p.price}</span>
                                    <button onClick={(e) => { e.stopPropagation(); addToCart(p); }} className="w-7 h-7 rounded-full bg-black text-white flex items-center justify-center shadow-md active:scale-90 hover:bg-primary transition-colors"><i className="fa-solid fa-plus text-xs"></i></button>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </div>
    );
};

