### Required SQL Scripts

To support the new profile features, execute the following SQL in your Supabase SQL editor. These commands create the necessary tables for contact messages and payout requests, and add missing columns to the existing tables.

```sql
-- 1. Create Payout Requests table
CREATE TABLE IF NOT EXISTS public.payout_requests (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    amount NUMERIC NOT NULL,
    method TEXT NOT NULL,
    status TEXT DEFAULT 'pending', -- pending, approved, rejected, paid
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Create Contact Messages table
CREATE TABLE IF NOT EXISTS public.contact_messages (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    message TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. Enhance existing Profiles table
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS address TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS theme_preference TEXT DEFAULT 'light';

-- 4. Enhance Couriers table
ALTER TABLE public.couriers ADD COLUMN IF NOT EXISTS transport_type TEXT;
ALTER TABLE public.couriers ADD COLUMN IF NOT EXISTS national_id_front_url TEXT;
ALTER TABLE public.couriers ADD COLUMN IF NOT EXISTS payout_method TEXT;
ALTER TABLE public.couriers ADD COLUMN IF NOT EXISTS delivery_radius NUMERIC DEFAULT 5;

-- 5. RLS Policies for new tables
ALTER TABLE public.payout_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can create payout requests" ON public.payout_requests FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can view own payout requests" ON public.payout_requests FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Admins can view all payout requests" ON public.payout_requests FOR SELECT USING (is_admin());
CREATE POLICY "Anyone can submit contact message" ON public.contact_messages FOR INSERT WITH CHECK (true);
CREATE POLICY "Admins can view contact messages" ON public.contact_messages FOR SELECT USING (is_admin());

