                     <i className="fa-solid fa-clock"></i>
                   </div>
                   <h2 className="text-xl font-bold mb-2 dark:text-white">Under Review</h2>
                   <p className="text-gray-500 dark:text-gray-400 mb-6 text-sm">Your store is pending admin approval. You cannot access the dashboard yet.</p>
                   <Button fullWidth onClick={() => { logout(); navigate('/login'); }}>Sign Out</Button>
               </div>
           </div>
       );
  }

  // New Check: If user is vendor role but has no profile, prompt to onboard
  if (!isDataLoading && !currentVendor && currentUser) {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg p-6 flex-col text-center">
              <div className="bg-white dark:bg-darkSurface p-8 rounded-2xl shadow-lg max-w-sm">
