                    <i className="fa-solid fa-store"></i>
                  </div>
                  <h2 className="text-xl font-bold mb-2 dark:text-white">Store Setup Incomplete</h2>
                  <p className="text-gray-500 dark:text-gray-400 mb-6 text-sm">You have a vendor account but haven't set up your store details yet.</p>
                  <Button fullWidth onClick={() => navigate('/vendor/onboarding')}>Complete Store Setup</Button>
              </div>
          </div>
      )
  }

  // Optimized Calculations
  const pendingOrders = useMemo(() => {
      return orders.filter(o => o.vendorId === vendorId && o.status !== 'delivered');
  }, [orders, vendorId]);

  const totalSales = useMemo(() => {
      return orders.filter(o => o.vendorId === vendorId).reduce((acc, curr) => {
          const saleValue = curr.total - (curr.deliveryFee || 0);
          return acc + saleValue;
      }, 0);
  }, [orders, vendorId]);

  return (
    <div className="p-4 min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in pb-safe">
        <div className="flex justify-between items-center mb-6">
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Dashboard</h1>
            <Button size="sm" onClick={() => navigate('/vendor/products/new')}>+ Add Product</Button>
        </div>

        <div className="grid grid-cols-2 gap-4 mb-6">
            <Card className="p-4 border-l-4 border-primary">
                <h3 className="text-gray-500 dark:text-gray-400 text-xs uppercase font-bold">Total Sales</h3>
                <p className="text-2xl font-bold mt-1 text-gray-900 dark:text-white">₵{totalSales.toFixed(2)}</p>
            </Card>
            <Card className="p-4 border-l-4 border-accent">
                <h3 className="text-gray-500 dark:text-gray-400 text-xs uppercase font-bold">Active Orders</h3>
                <p className="text-2xl font-bold mt-1 text-gray-900 dark:text-white">{pendingOrders.length}</p>
            </Card>
        </div>

        <h3 className="font-bold text-lg mb-3 text-gray-800 dark:text-white">Recent Orders</h3>
        <div className="space-y-3 mb-8">
            {pendingOrders.length === 0 ? <p className="text-gray-500 dark:text-gray-400 text-sm bg-white dark:bg-darkSurface p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-800">No active orders.</p> : 
             pendingOrders.slice(0, 3).map(order => (
                 <Card key={order.id} className="p-4" onClick={() => navigate('/vendor/orders')}>
                     <div className="flex justify-between mb-2">
