      {/* Filter Pills */}
      <div className="px-4 -mt-2">
         <div className="flex gap-2 overflow-x-auto hide-scrollbar py-2">
            <FilterButton type="nearby" label="Nearby" />
            <FilterButton type="price" label="Low Price" />
            <FilterButton type="rating" label="Top Rated" />
