                 {[...Array(10)].map((_, i) => <ProductCardSkeleton key={i} />)}
             </div>
         ) : sortedProducts.length === 0 ? (
             <div className="flex flex-col items-center justify-center py-20 text-gray-400 dark:text-gray-500 bg-white dark:bg-darkSurface rounded-2xl border border-dashed border-gray-200 dark:border-gray-800 mx-1">
