                    const mainImage = product.images && product.images.length > 0 ? product.images[0] : 'https://via.placeholder.com/300';
                    const isFav = favorites.includes(product.id);
                    const isInCart = cart.some(item => item.productId === product.id);

                    return (
                        <div 
                            key={product.id} 
                            className="bg-white dark:bg-darkSurface rounded-2xl overflow-hidden shadow-card border border-gray-100 dark:border-gray-800 hover:shadow-xl transition-all duration-300 group relative flex flex-col h-full cursor-pointer"
                            onClick={() => navigate(`/buyer/product/${product.id}`)}
                        >
                             {/* Image - Square Aspect Ratio for Compactness */}
                            <div className="aspect-square w-full relative overflow-hidden bg-white dark:bg-gray-900">
                                <img 
                                    src={mainImage} 
                                    alt={product.title} 
                                    className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
                                />

                                {/* Location Badge - Glass Effect on Top Left */}
                                <div className="absolute top-2 left-2 bg-white/80 dark:bg-darkBg/80 backdrop-blur-md px-2 py-1 rounded-lg text-[10px] font-bold border border-white/50 dark:border-white/5 shadow-sm flex items-center gap-1 z-20 text-gray-700 dark:text-gray-300">
                                     <i className="fa-solid fa-location-dot text-primary text-[9px]"></i> {product.location}
                                </div>

                                {/* WhatsApp Quick Contact (New Restored Indicator) */}
                                {vendor?.contactPhone && (
                                    <div className="absolute bottom-2 left-2 z-20 bg-[#25D366]/90 backdrop-blur-sm p-1.5 rounded-lg shadow-md flex items-center gap-1.5 border border-white/20">
                                         <i className="fa-brands fa-whatsapp text-white text-[10px]"></i>
                                         <span className="text-white text-[8px] font-black uppercase tracking-tighter">Chat Now</span>
                                    </div>
                                )}

                                {/* Fav Button (Floating) */}
                                <button 
                                    className="absolute top-2 right-2 z-10 w-7 h-7 rounded-full bg-white/80 dark:bg-darkBg/80 backdrop-blur-sm border border-gray-100 dark:border-gray-800 hover:border-red-100 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors shadow-sm active:scale-90"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        toggleFavorite(product.id);
                                    }}
                                >
                                    <i className={`${isFav ? 'fa-solid text-red-500' : 'fa-regular'} fa-heart text-xs`}></i>
                                </button>

                                {product.stock === 0 && <div className="absolute inset-0 bg-black/40 flex items-center justify-center z-10"><span className="bg-black/80 text-white text-[10px] px-3 py-1 rounded font-bold uppercase tracking-wide">Out of Stock</span></div>}
                            </div>

                            {/* Bottom Details - Increased Font Sizes */}
                            <div className="p-3 bg-white dark:bg-darkSurface flex flex-col justify-between flex-grow relative z-10">
                                <div>
                                    <h3 className="text-sm text-gray-800 dark:text-white font-bold leading-tight line-clamp-2 mb-1">{product.title}</h3>
                                    <p className="text-[11px] text-gray-400 dark:text-gray-500 line-clamp-1">{vendor?.storeName}</p>
                                </div>

                                <div className="flex items-center justify-between mt-2">
                                    <span className="text-lg font-extrabold text-gray-900 dark:text-white">{product.currency}{product.price.toFixed(2)}</span>
                                    <button 
                                        className={`w-8 h-8 rounded-full flex items-center justify-center text-white transition-all shadow-md active:scale-90 group-btn ${product.stock === 0 ? 'bg-gray-300 dark:bg-gray-700 cursor-not-allowed' : isInCart ? 'bg-green-500 hover:bg-red-500' : 'bg-black dark:bg-white dark:text-black hover:bg-primary'}`}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            if (product.stock > 0) {
                                                if (isInCart) {
                                                    removeFromCart(product.id);
                                                    showToast('Removed from Cart', 'info');
                                                } else {
                                                    addToCart(product);
                                                }
                                            }
                                        }}
                                        disabled={product.stock === 0}
                                    >
                                        <i className={`fa-solid ${isInCart ? 'fa-check group-btn-hover:fa-trash' : 'fa-plus'} text-xs ${isInCart ? 'group-hover:hidden' : ''}`}></i>
                                        {isInCart && <i className="fa-solid fa-trash text-xs hidden group-hover:inline"></i>}
                                    </button>
                                </div>
                            </div>
                        </div>
                    )
                })}
            </div>
         )}
      </div>
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, Courier, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

type ThemeMode = 'light' | 'dark' | 'system';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  couriers: Courier[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  connectionError: boolean;
  favorites: string[];
  toast: ToastMessage | null;
  theme: ThemeMode;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => Promise<{success: boolean, error?: string, user?: any}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;
  updateTheme: (theme: ThemeMode) => void;

  updateProfile: (data: Partial<User>) => Promise<{ success: boolean }>;
  submitContactMessage: (name: string, email: string, message: string) => Promise<{ success: boolean }>;
  requestPayout: (amount: number, method: string) => Promise<{ success: boolean }>;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerCourier: (data: Partial<Courier> & { phoneNumber?: string }, explicitUserId?: string) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveCourier: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  toggleDriverStatus: (isOnline: boolean) => Promise<void>;
  updateDriverLocation: (lat: number, lng: number) => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

const resolveCoordinates = (locationName: string): {lat: number, lng: number} | undefined => {
    const clean = locationName.toLowerCase().trim();
    if (INITIAL_LOCATION_CACHE[clean]) {
        return { lat: INITIAL_LOCATION_CACHE[clean][0], lng: INITIAL_LOCATION_CACHE[clean][1] };
    }
    const key = Object.keys(INITIAL_LOCATION_CACHE).find(k => clean.includes(k));
    if (key) {
        return { lat: INITIAL_LOCATION_CACHE[key][0], lng: INITIAL_LOCATION_CACHE[key][1] };
    }
    return { lat: 5.6506, lng: -0.1962 };
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [couriers, setCouriers] = useState<Courier[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [theme, setTheme] = useState<ThemeMode>(() => {
      // Initial FOUC prevention load
      try { return (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system'; } catch { return 'system'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [connectionError, setConnectionError] = useState<boolean>(false);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);

  useEffect(() => { 
      if (currentRole !== 'guest' && currentRole !== 'admin') {
          safeSetItem('lynqed_role', currentRole); 
      }
  }, [currentRole]);

  // Load user-specific theme when currentUser changes
  useEffect(() => {
    if (currentUser) {
        const userTheme = localStorage.getItem(`lynqed_theme_${currentUser.id}`) as ThemeMode;
        if (userTheme) setTheme(userTheme);
    } else {
        // Revert to guest or system theme on logout
        const guestTheme = (localStorage.getItem('lynqed_theme_last') as ThemeMode) || 'system';
        setTheme(guestTheme);
    }
  }, [currentUser]);

  // Handle Theme Application
  useEffect(() => {
    const applyTheme = (mode: ThemeMode) => {
        const root = window.document.documentElement;
        let isDark = mode === 'dark';
        if (mode === 'system') {
            isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        }

        if (isDark) {
            root.classList.add('dark');
        } else {
            root.classList.remove('dark');
        }

        // Always update "last" key for FOUC prevention on refresh
        safeSetItem('lynqed_theme_last', mode);

        // Update user-specific key if logged in
        if (currentUser) {
            safeSetItem(`lynqed_theme_${currentUser.id}`, mode);
        }
    };

    applyTheme(theme);

    // Watch for system preference changes if in system mode
    if (theme === 'system') {
        const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
        const handler = () => applyTheme('system');
        mediaQuery.addEventListener('change', handler);
        return () => mediaQuery.removeEventListener('change', handler);
    }
  }, [theme, currentUser]);

  const updateTheme = (newTheme: ThemeMode) => setTheme(newTheme);

  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;
          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);
          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);
          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  useEffect(() => {
    initApp();
    try {
        const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
        const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
              fetchData();
              if (payload.eventType === 'INSERT') {
                  const newOrder = payload.new as Order;
                  const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;
                  if (currentRoleRef.current === 'vendor' && myVendorId && newOrder.vendorId === myVendorId) {
                      playNotificationSound();
                      setToast({ message: "🔔 New Order Received!", type: "info" });
                  }
              }
              if (payload.eventType === 'UPDATE') {
                  const updatedOrder = payload.new as any;
                  if (currentRoleRef.current === 'courier' && updatedOrder.status === 'ready_for_pickup' && !updatedOrder.courier_id) {
                       setToast({ message: "📦 New Job Available Nearby", type: "info" });
                  }
              }
          }).subscribe();

        const courierSub = supabase.channel('public:couriers').on('postgres_changes', { event: '*', schema: 'public', table: 'couriers' }, () => fetchData()).subscribe();

        return () => {
            supabase.removeChannel(productSub);
            supabase.removeChannel(orderSub);
            supabase.removeChannel(courierSub);
        };
    } catch (e) {
        console.error("Realtime subscription failed:", e);
    }
  }, []); 

  const initApp = async () => {
      try {
          await checkSession();
          await fetchData();
          setConnectionError(false);
      } catch (e: any) {
          console.error("Initialization Failed:", e);
      } finally {
          setIsLoading(false);
          setIsDataLoading(false);
      }
  };

  const checkSession = async () => {
      try {
          const { data, error } = await supabase.auth.getSession();
          if (error) throw error;
          if (data.session?.user) {
              await fetchUserProfile(data.session.user.id, data.session.user);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e: any) { 
          console.error("Session check error:", e);
      } 
  };

  const fetchUserProfile = async (userId: string, sessionUser?: any): Promise<User | null> => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();

          if (error) throw error;
          if (data) {
              if (data.isBanned) throw new Error("Account Suspended");

              const user: User = { 
                  ...data, 
                  roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url,
                  phoneNumber: data.phone_number,
                  defaultLocation: data.address
              };

              setCurrentUser(user);

              // Role Detection Logic
              let finalRole: Role = 'buyer';
              if (user.roles.includes('admin')) {
                  finalRole = 'admin';
              } else if (persistedRole && user.roles.includes(persistedRole)) {
                  finalRole = persistedRole;
              } else if (user.roles.includes('courier')) {
                  finalRole = 'courier';
              } else if (user.roles.includes('vendor')) {
                  finalRole = 'vendor';
              }

              setCurrentRole(finalRole);
              if (finalRole !== 'guest') safeSetItem('lynqed_role', finalRole);

              return user;
          } else if (sessionUser) {
              const { error: insertError } = await supabase.from('profiles').insert({
                  id: userId,
                  email: sessionUser.email,
                  name: sessionUser.user_metadata?.full_name || sessionUser.email?.split('@')[0] || 'New User',
                  roles: ['buyer']
              });
              if (!insertError) return fetchUserProfile(userId, undefined);
          }
      } catch (e: any) {
          console.error("Profile fetch error", e);
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, select = '*', orderBy?: string) => {
             try {
                let query = supabase.from(table).select(select);
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                if (error) throw error;
                return data;
             } catch (e: any) { 
                 return null;
             }
          };

          const [pData, vData, oData, cDataRaw] = await Promise.all([
              fetchSafely('products', '*', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', '*', 'created_at'),
              fetchSafely('couriers')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendor_id, 
              contactPhone: p.contact_phone,
          })) as Product[]);

          if (vData) setVendors(vData.map((v: any) => ({
              ...v,
              vendorId: v.vendor_id, 
              storeName: v.store_name,
              storeDescription: v.store_description,
              storeAvatarUrl: v.store_avatar_url,
              userId: v.user_id,
              isApproved: v.is_approved,
              contactPhone: v.contact_phone // FIXED: Map contact_phone to contactPhone
          })) as Vendor[]);

          if (oData) setOrders(oData.map((o: any) => ({
              ...o, 
              vendorId: o.vendor_id,
              buyerId: o.buyer_id,
              courierId: o.courier_id,
              deliveryFee: o.delivery_fee,
              deliveryOption: o.delivery_option,
              createdAt: o.created_at,
              items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items,
              locationCoordinates: o.location_coordinates,
              pickupCoordinates: o.pickup_coordinates,
          })) as Order[]);

          if (cDataRaw) {
              const userIds = [...new Set(cDataRaw.map((d: any) => d.user_id).filter(Boolean))];
              const { data: profiles } = await supabase.from('profiles').select('id, name, email').in('id', userIds);
              const profileMap = new Map<string, any>(profiles?.map((p: any) => [p.id, p]) || []);
              setCouriers(cDataRaw.map((d: any) => ({
                  ...d,
                  userId: d.user_id,
                  fullName: profileMap.get(d.user_id)?.name || d.full_name || 'Courier',
                  vehicleType: d.vehicle_type,
                  onlineStatus: d.online_status,
                  status: d.status,
                  verified: d.status === 'approved',
                  payoutMethod: d.payout_method
              })) as Courier[]);
          }

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await supabase.from('profiles').select('*');
              if (uData.data) setUsers(uData.data as any);
          }
      } catch (e: any) { 
          console.error("Data Fetch Error:", e);
      } finally { 
          setIsDataLoading(false); 
      }
  };

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      if (data.user) {
          const user = await fetchUserProfile(data.user.id, data.user);
          if (!user) return { success: false, error: "Profile missing" };

          fetchData();

          // CRITICAL: Determine actual role from user profile rather than stale currentRole state
          let detectedRole: Role = 'buyer';
          if (user.roles.includes('admin')) detectedRole = 'admin';
          else if (user.roles.includes('vendor')) detectedRole = 'vendor';
          else if (user.roles.includes('courier')) detectedRole = 'courier';

          return { success: true, role: detectedRole }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role, phoneNumber?: string) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ 
               id: data.user.id, email, name: fullName, roles: [role], phone_number: phoneNumber 
           });
           await login(email, password); 
           return { success: true, user: data.user };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
          redirectTo: window.location.origin + '/update-password',
      });
      return { success: !error, error: error?.message };
  };

  const updatePassword = async (password: string) => {
      const { error } = await supabase.auth.updateUser({ password });
      return { success: !error, error: error?.message };
  };

  const switchRole = (role: Role) => { 
      if(currentUser?.roles.includes(role)) {
          setCurrentRole(role); 
          safeSetItem('lynqed_role', role);
          showToast(`Switched to ${role.charAt(0).toUpperCase() + role.slice(1)} Mode`, 'info');
      }
  };

  const updateProfile = async (data: Partial<User>) => {
      if(!currentUser) return { success: false };

      const updatePayload: any = {};
      if (data.name) updatePayload.name = data.name;
      if (data.avatarUrl) updatePayload.avatar_url = data.avatarUrl;
      if (data.phoneNumber) updatePayload.phone_number = data.phoneNumber;
      if (data.address) updatePayload.address = data.address;

      const { error } = await supabase.from('profiles').update(updatePayload).eq('id', currentUser.id);

      if(!error) {
          showToast("Profile updated", "success");
          setCurrentUser(prev => prev ? ({ ...prev, ...data }) : null);
          fetchUserProfile(currentUser.id);
          return { success: true };
      }
      return { success: false };
  };

  const submitContactMessage = async (name: string, email: string, message: string) => {
      const { error } = await supabase.from('contact_messages').insert({ name, email, message });
      if(!error) showToast("Message sent!", "success");
      return { success: !error };
  };

  const requestPayout = async (amount: number, method: string) => {
      if(!currentUser) return { success: false };
      const { error } = await supabase.from('payout_requests').insert({ 
          user_id: currentUser.id, amount, method, status: 'pending' 
      });
      if(!error) showToast("Payout requested", "success");
      return { success: !error };
  };

  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileName = `${Math.random().toString(36).substring(2)}_${Date.now()}.${file.name.split('.').pop()}`;
          const filePath = `${folder}/${fileName}`;
          const { error: uploadError } = await supabase.storage.from('lynqed-assets').upload(filePath, file);
          if (uploadError) throw uploadError;
          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const { error } = await supabase.from('vendors').upsert({ 
          vendor_id: `v-${Date.now()}`, user_id: currentUser.id, store_name: data.storeName,
          store_description: data.storeDescription, location: data.location,
          contact_phone: data.contactPhone, store_avatar_url: data.storeAvatarUrl,
          is_approved: false, rating: 5.0 
      });
      if (!error) {
          const roles = [...new Set([...currentUser.roles, 'vendor' as Role])];
          await supabase.from('profiles').update({ roles }).eq('id', currentUser.id);
          showToast("Store profile saved", "success"); fetchData(); return { success: true };
      }
      return { success: false };
  };

  const registerCourier = async (data: any, explicitUserId?: string): Promise<{ success: boolean }> => {
      const uid = explicitUserId || currentUser?.id;
      if(!uid) return { success: false };
      const { error } = await supabase.from('couriers').insert({ 
          user_id: uid, status: 'pending', full_name: data.fullName,
          vehicle_type: data.vehicleType, transport_type: data.transportType,
          payout_method: data.payoutMethod, delivery_radius: data.deliveryRadius
      });
      if(!error) { showToast("Application submitted", "success"); fetchData(); return { success: true }; }
      return { success: false };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) return false;
      const v = vendors.find(v => v.userId === currentUser.id);
      if(!v) return false;
      const { error } = await supabase.from('products').insert({
          vendor_id: v.vendorId, title: prod.title, description: prod.description,
          price: prod.price, category: prod.category, images: prod.images,
          stock: prod.stock, status: 'pending', location: prod.location,
          contact_phone: prod.contactPhone
      });
      if (!error) { showToast("Product submitted", "success"); fetchData(); return true; }
      return false;
  };

  const updateProduct = async (id: string, data: any) => {
      const { error } = await supabase.from('products').update({ ...data, contact_phone: data.contactPhone }).eq('id', id);
      if (!error) { showToast("Product updated", "success"); fetchData(); }
  };

  const deleteProduct = async (id: string) => { await supabase.from('products').delete().eq('id', id); fetchData(); };
  const updateProductStatus = async (id: string, status: string) => { await supabase.from('products').update({status}).eq('id', id); fetchData(); };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const borderCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      if (favorites.includes(pid)) setFavorites(prev => prev.filter(i => i !== pid));
      else setFavorites(prev => [...prev, pid]);
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const vendor = vendors.find(v => v.vendorId === vid);
              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, vendor_id: vid, items, 
                  total: subtotal+fee, delivery_fee: fee, status: 'placed', 
                  delivery_option: option, pickup_coordinates: vendor ? resolveCoordinates(vendor.location) : undefined,
                  location_coordinates: resolveCoordinates(currentUser.address || 'campus')
              });
              if (error) throw error;
              for (const item of items) {
                  await supabase.from('products').update({ stock: Math.max(0, item.product.stock - item.quantity) }).eq('id', item.productId);
              }
          }
          showToast("Order Placed!", "success"); setCart([]); fetchData();
      } catch (e: any) {
          showToast("Order failed", "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => {
      if (!currentUser) return;
      const { error } = await supabase.from('orders').update({ courier_id: currentUser.id, status: 'courier_assigned' }).eq('id', oid);
      if (!error) { showToast("Job Accepted!", "success"); fetchData(); }
  };

  const toggleDriverStatus = async (isOnline: boolean) => {
      if(!currentUser) return;
      const c = couriers.find(d => d.userId === currentUser.id);
      if(c) {
          await supabase.from('couriers').update({ online_status: isOnline }).eq('id', c.id);
          fetchData();
      }
  };

  const updateDriverLocation = async (lat: number, lng: number) => {
      if(!currentUser) return;
      const c = couriers.find(d => d.userId === currentUser.id);
      if(c) supabase.from('couriers').update({ current_lat: lat, current_lng: lng }).eq('id', c.id).then();
  };

  const banUser = async (uid: string, s: boolean) => { await supabase.from('profiles').update({isBanned: s}).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { await supabase.from('profiles').delete().eq('id', uid); fetchData(); };
  const approveVendor = async (vid: string, s: boolean) => { await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); fetchData(); };
  const approveCourier = async (id: string, uid: string, status: string) => { 
      await supabase.from('couriers').update({ status }).eq('id', id);
      if(status === 'approved') {
          const { data } = await supabase.from('profiles').select('roles').eq('id', uid).single();
          if(data && !data.roles.includes('courier')) {
              await supabase.from('profiles').update({ roles: [...data.roles, 'courier'] }).eq('id', uid);
          }
      }
      fetchData(); 
  };

  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, couriers, users, isLoading, isDataLoading, connectionError, cart, favorites, toast, theme,
        login, signup, logout, resetPassword, updatePassword, switchRole, updateTheme,
        updateProfile, submitContactMessage, requestPayout,
        uploadFile, registerVendor, registerCourier, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart: () => setCart([]), placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveCourier,
        toggleDriverStatus, updateDriverLocation,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useApp } from '../context';
import { Button, Badge, Card, Input, Avatar, Spinner } from '../components/UI';
import { Product } from '../types';

export const StorePage: React.FC = () => {
    const { vendorId } = useParams<{ vendorId: string }>();
    const navigate = useNavigate();
    const { vendors, products, addToCart, cart, removeFromCart, toggleFavorite, favorites, showToast } = useApp();

    const vendor = vendors.find(v => v.vendorId === vendorId);
    const vendorProducts = products.filter(p => p.vendorId === vendorId && p.status === 'approved');

    if (!vendor) return <div className="p-8 text-center text-gray-500 dark:text-gray-400">Store not found</div>;

    const whatsappUrl = vendor.contactPhone 
        ? `https://wa.me/${vendor.contactPhone.replace(/[^0-9]/g, '').replace(/^0/, '233')}?text=Hi ${vendor.storeName}, I saw your store on LYNQED!`
        : null;

    const handleShare = async () => {
        const shareData = {
            title: `Check out ${vendor.storeName} on LYNQED!`,
            text: `Find amazing products at ${vendor.storeName} on campus.`,
            url: window.location.href
        };

        try {
            if (navigator.share) {
                await navigator.share(shareData);
            } else {
                await navigator.clipboard.writeText(window.location.href);
                showToast("Store link copied to clipboard!", "success");
            }
        } catch (err) {
            console.error("Error sharing:", err);
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            {/* Store Header */}
            <div className="bg-white dark:bg-darkSurface p-6 shadow-sm border-b border-gray-100 dark:border-gray-800">
                <div className="flex items-center gap-4">
                     <Avatar src={vendor.storeAvatarUrl} name={vendor.storeName} size="xl" />
                     <div className="flex-1">
                         <div className="flex items-center gap-2">
                            <h1 className="text-xl font-display font-bold text-gray-900 dark:text-white">{vendor.storeName}</h1>
                            {vendor.isApproved && <i className="fa-solid fa-circle-check text-blue-500 text-sm"></i>}
                         </div>
                         <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400 mt-1 mb-2">
                             <i className="fa-solid fa-location-dot text-red-500"></i> {vendor.location}
                             <span className="mx-1">•</span>
                             <i className="fa-solid fa-star text-yellow-400"></i> {vendor.rating}
                         </div>
                         <p className="text-sm text-gray-600 dark:text-gray-400 line-clamp-2">{vendor.storeDescription}</p>
                     </div>
                </div>

                {/* Actions */}
                <div className="grid grid-cols-2 gap-3 mt-4">
                     {whatsappUrl && (
                        <a 
                            href={whatsappUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="flex items-center justify-center gap-2 bg-[#25D366] text-white py-2.5 rounded-xl text-sm font-bold hover:bg-[#128C7E] transition-all shadow-md active:scale-95"
                        >
                            <i className="fa-brands fa-whatsapp text-lg"></i> Chat on WhatsApp
                        </a>
                     )}
                     <button 
                        onClick={handleShare}
                        className="flex items-center justify-center gap-2 bg-gray-50 dark:bg-gray-800 text-gray-600 dark:text-gray-400 py-2.5 rounded-xl text-sm font-bold hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors border border-gray-100 dark:border-gray-700"
                    >
                        <i className="fa-solid fa-share-nodes"></i> Share Store
                     </button>
                </div>
            </div>

            {/* Product Grid */}
            <div className="p-4">
                <h2 className="font-bold text-gray-800 dark:text-gray-200 mb-4 text-sm uppercase tracking-wide">Products ({vendorProducts.length})</h2>
                {vendorProducts.length === 0 ? (
                    <div className="text-center py-10 text-gray-400 dark:text-gray-500">No products available.</div>
                ) : (
                    <div className="grid grid-cols-2 gap-3">
                        {vendorProducts.map(product => {
                            const isFav = favorites.includes(product.id);
                            const isInCart = cart.some(item => item.productId === product.id);

                            return (
                                <div 
                                    key={product.id} 
                                    className="bg-white dark:bg-darkSurface rounded-2xl overflow-hidden shadow-card border border-gray-100 dark:border-gray-800 hover:shadow-xl transition-all duration-300 group relative flex flex-col h-full cursor-pointer"
                                    onClick={() => navigate(`/buyer/product/${product.id}`)}
                                >
                                    <div className="aspect-[4/5] w-full relative overflow-hidden bg-white dark:bg-gray-900">
                                        <img 
                                            src={product.images[0]} 
                                            alt={product.title} 
                                            className="w-full h-full object-cover p-0 transition-transform duration-700 group-hover:scale-110" 
                                        />
                                        <button 
                                            className="absolute top-2 right-2 z-10 w-7 h-7 rounded-full bg-white/80 dark:bg-darkBg/80 backdrop-blur-sm border border-gray-100 dark:border-gray-800 hover:border-red-100 text-gray-400 hover:text-red-500 flex items-center justify-center transition-colors shadow-sm active:scale-90"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                toggleFavorite(product.id);
                                            }}
                                        >
                                            <i className={`${isFav ? 'fa-solid text-red-500' : 'fa-regular'} fa-heart text-xs`}></i>
                                        </button>
                                        {product.stock === 0 && <div className="absolute inset-0 bg-black/40 flex items-center justify-center z-10"><span className="bg-black/80 text-white text-[10px] px-3 py-1 rounded font-bold uppercase tracking-wide">Out of Stock</span></div>}
                                    </div>
                                    <div className="p-3 bg-white dark:bg-darkSurface flex flex-col justify-between flex-grow relative z-10">
                                        <div>
                                            <h3 className="text-xs text-gray-800 dark:text-white font-bold leading-tight line-clamp-2 mb-1">{product.title}</h3>
                                        </div>
                                        <div className="flex items-center justify-between mt-2">
                                            <span className="text-sm font-extrabold text-gray-900 dark:text-white">{product.currency}{product.price.toFixed(2)}</span>
                                            <button 
                                                className={`w-8 h-8 rounded-full flex items-center justify-center text-white transition-all shadow-md active:scale-90 group-btn ${product.stock === 0 ? 'bg-gray-300 dark:bg-gray-700 cursor-not-allowed' : isInCart ? 'bg-green-500 hover:bg-red-500' : 'bg-black dark:bg-white dark:text-black hover:bg-primary'}`}
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    if (product.stock > 0) {
                                                        isInCart ? removeFromCart(product.id) : addToCart(product);
                                                    }
                                                }}
                                                disabled={product.stock === 0}
                                            >
                                                <i className={`fa-solid ${isInCart ? 'fa-check group-btn-hover:fa-trash' : 'fa-plus'} text-xs ${isInCart ? 'group-hover:hidden' : ''}`}></i>
                                                {isInCart && <i className="fa-solid fa-trash text-xs hidden group-hover:inline"></i>}
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
};

export const ProductDetail: React.FC = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { products, addToCart, cart, removeFromCart, updateCartQuantity, vendors, favorites, toggleFavorite, showToast } = useApp();
    const [selectedImageIndex, setSelectedImageIndex] = useState(0);

    const product = products.find(p => p.id === id);
    const vendor = vendors.find(v => v.vendorId === product?.vendorId);

    // Recommendations
    const relatedProducts = products
        .filter(p => p.category === product?.category && p.id !== product?.id)
        .slice(0, 4);

    const [quantity, setQuantity] = useState(1);

    if (!product) return <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-darkBg"><Spinner /></div>;

    const cartItem = cart.find(i => i.productId === product.id);
    const isInCart = !!cartItem;
    const isFav = favorites.includes(product.id);

    // Sync local quantity with cart if present
    useEffect(() => {
        if (cartItem) setQuantity(cartItem.quantity);
    }, [cartItem]);

    const handleQuantity = (delta: number) => {
        const newQ = Math.max(1, Math.min(product.stock, quantity + delta));
        setQuantity(newQ);
        if (isInCart) updateCartQuantity(product.id, newQ);
    };

    const handleBuyNow = () => {
        if (isInCart) {
            updateCartQuantity(product.id, quantity);
        } else {
            addToCart(product, quantity);
        }
        navigate('/buyer/checkout');
    };

    const handleShare = async () => {
        const shareData = {
            title: product.title,
            text: `Check out this ${product.title} from ${vendor?.storeName || 'LYNQED'}!`,
            url: window.location.href
        };

        try {
            if (navigator.share) {
                await navigator.share(shareData);
            } else {
                await navigator.clipboard.writeText(window.location.href);
                showToast("Product link copied to clipboard!", "success");
            }
        } catch (err) {
            console.error("Error sharing:", err);
        }
    };

    const whatsappUrl = vendor?.contactPhone 
        ? `https://wa.me/${vendor.contactPhone.replace(/[^0-9]/g, '').replace(/^0/, '233')}?text=Hi ${vendor.storeName}, I saw your product "${product.title}" on LYNQED and I'm interested!`
        : null;

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-darkBg pb-20 animate-fade-in">
            {/* Breadcrumbs & Header */}
            <div className="bg-white dark:bg-darkSurface border-b border-gray-200 dark:border-gray-800 sticky top-0 z-30 px-4 py-3 flex items-center gap-3 shadow-sm">
                <button onClick={() => navigate(-1)} className="text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white">
                    <i className="fa-solid fa-arrow-left"></i>
                </button>
                <div className="text-xs text-gray-500 dark:text-gray-400 breadcrumbs flex items-center gap-2 overflow-hidden whitespace-nowrap">
                    <Link to="/buyer/dashboard" className="hover:text-primary dark:hover:text-primaryLight">Home</Link>
                    <i className="fa-solid fa-chevron-right text-[8px]"></i>
                    <span>{product.category}</span>
                    <i className="fa-solid fa-chevron-right text-[8px]"></i>
                    <span className="text-gray-900 dark:text-white font-bold truncate">{product.title}</span>
                </div>
                <div className="ml-auto flex gap-3">
                    <button onClick={() => toggleFavorite(product.id)} className={`${isFav ? 'text-red-500' : 'text-gray-400 dark:text-gray-500'} hover:text-red-600 transition-colors`}>
                        <i className={`${isFav ? 'fa-solid' : 'fa-regular'} fa-heart text-lg`}></i>
                    </button>
                    <button onClick={handleShare} className="text-gray-400 dark:text-gray-500 hover:text-blue-500">
                        <i className="fa-solid fa-share-nodes text-lg"></i>
                    </button>
