                 <Button onClick={() => navigate('/vendor/onboarding')}>Set Up Store</Button>
             </div>
         );
    }

    const myProducts = products.filter(p => p.vendorId === currentVendor?.vendorId);

    return (
        <div className="p-4 min-h-screen bg-gray-50 dark:bg-darkBg pb-24 animate-fade-in pb-safe">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-xl font-bold text-gray-900 dark:text-white">My Products</h1>
                <Button size="sm" onClick={() => navigate('/vendor/products/new')}>Add New</Button>
            </div>

            <div className="space-y-4">
                {myProducts.length === 0 ? <div className="text-center py-10 text-gray-400 dark:text-gray-500">No products added yet.</div> : (
                    myProducts.map(p => (
