                            <div className="w-16 h-16 rounded-xl bg-gray-100 dark:bg-gray-900 flex-shrink-0 overflow-hidden relative">
                                <img src={p.images[0]} className="w-full h-full object-cover" />
                            </div>
                            <div className="flex-grow">
                                <h4 className="font-bold text-sm text-gray-900 dark:text-white line-clamp-1">{p.title}</h4>
                                <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 mt-1">
                                    <span>{p.stock} left</span>
                                </div>
                                <p className="font-bold text-primary dark:text-primaryLight text-sm mt-1">{p.currency}{p.price}</p>
                            </div>
                            <div className="flex flex-col items-end gap-2">
                                <Badge color={p.status === 'approved' ? 'green' : p.status === 'rejected' ? 'red' : 'yellow'}>{p.status}</Badge>
